function initials(name: string): string {
  const parts = name.trim().split(/\s+/)
  const first = parts[0]?.[0] ?? ""
  const last = parts.length > 1 ? parts[parts.length - 1]?.[0] ?? "" : ""
  return (first + last).toUpperCase()
}

export function Avatar({ name, src, size = 56 }: { name: string; src?: string; size?: number }) {
  if (src) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img
        src={src}
        alt={name}
        style={{
          width: size,
          height: size,
          borderRadius: "var(--atlas-radius-full)",
          objectFit: "cover",
        }}
      />
    )
  }
  return (
    <div
      role="img"
      aria-label={name}
      style={{
        width: size,
        height: size,
        borderRadius: "var(--atlas-radius-full)",
        backgroundColor: "var(--atlas-primary-subtle)",
        color: "var(--atlas-primary)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "var(--atlas-text-h3)",
        fontWeight: "var(--atlas-font-weight-semibold)",
        flexShrink: 0,
      }}
    >
      {initials(name)}
    </div>
  )
}

